def compute(vars):
    start_value = vars["v1"]
    end_value = vars["v2"]
    years = 2017 - 2012

    if start_value == 0:
        return None

    annualized_return = ((end_value / start_value) ** (1 / years) - 1) * 100

    return {
        "value": annualized_return,
        "trace": {
            "start_value": start_value,
            "end_value": end_value,
            "years": years,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
